"""Assemble the standalone V2.2 strategy from the shared market core and runtime."""

import argparse
import hashlib
from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[2]
EXPERIMENTAL = ROOT / "unified/experimental"
CORE = EXPERIMENTAL / "v22/market_core.pineinc"
RUNTIME = EXPERIMENTAL / "v22/strategy_runtime.pineinc"
OUTPUT = EXPERIMENTAL / "QIRVANTA_SNIPER_V22_STRATEGY.pine"
DIGEST_TOKEN = b"__V22_TEMPLATE_SHA__"
PINE_FUNCTION = re.compile(rb"^([A-Za-z_]\w*)\([^\n]*\)\s*=>", re.MULTILINE)
HEADER = b'''//@version=6
// Generated by unified.tools.build_v22_strategy.
strategy("QIRVANTA SNIPER PREMIUM V2.2 Strategy", shorttitle="QIRV V2.2", overlay=true, behind_chart=false,
     initial_capital=100000, currency=currency.USD, pyramiding=0, default_qty_type=strategy.fixed,
     default_qty_value=3, commission_type=strategy.commission.cash_per_contract, commission_value=0.175,
     slippage=2, calc_on_every_tick=false, calc_on_order_fills=false, process_orders_on_close=false,
     use_bar_magnifier=false, margin_long=100, margin_short=100, max_bars_back=1000)
'''


def sha(data):
    return hashlib.sha256(data).hexdigest()


def assemble(bars=0):
    if bars < 0:
        raise ValueError("Use a nonnegative calculated bar count")
    header = HEADER
    if bars:
        header = header.replace(b"max_bars_back=1000)", f"max_bars_back=1000, calc_bars_count={bars})".encode("ascii"))
    core, runtime = CORE.read_bytes(), RUNTIME.read_bytes()
    duplicates = set(PINE_FUNCTION.findall(core)) & set(PINE_FUNCTION.findall(runtime))
    if duplicates:
        raise ValueError(f"Shared core and strategy declare the same helpers: {sorted(duplicates)}")
    chunks = (header, core, runtime)
    template = b"\n\n".join(chunk.replace(b"\r\n", b"\n").rstrip() for chunk in chunks) + b"\n"
    if template.count(DIGEST_TOKEN) != 1:
        raise ValueError("Expected a single native journal source identity token")
    identity = sha(template)
    return template.replace(DIGEST_TOKEN, identity.encode("ascii")), identity


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Validate the existing output without writing")
    parser.add_argument("--bars", type=int, default=0, help="Use a bounded diagnostic history")
    parser.add_argument("--output", type=Path, default=OUTPUT)
    args = parser.parse_args()
    if args.bars and args.output.resolve() == OUTPUT.resolve():
        parser.error("Use a separate output path for bounded diagnostics")
    data, identity = assemble(args.bars)
    if args.check:
        if args.output.read_bytes() != data:
            parser.error("Generated strategy differs from the checked file")
    else:
        args.output.write_bytes(data)
    print(f"{args.output.name} sha256={sha(data)} template_sha256={identity} bytes={len(data)}")


if __name__ == "__main__":
    main()
